package findu.backend.founditem.dto; import findu.backend.founditem.entity.FoundItem; import lombok.Builder; @Builder public record FoundItemResponseDto(Long id, Long userId, String nickname, Long categoryId, String categoryName, String title, String description, String imageUrl, String location, java.time.LocalDateTime foundAt, java.time.LocalDateTime createdAt){public static FoundItemResponseDto from(FoundItem x){return builder().id(x.getId()).userId(x.getUser().getId()).nickname(x.getUser().getNickname()).categoryId(x.getCategory().getId()).categoryName(x.getCategory().getName()).title(x.getTitle()).description(x.getDescription()).imageUrl(x.getImageUrl()).location(x.getLocation()).foundAt(x.getFoundAt()).createdAt(x.getCreatedAt()).build();}}
